INSERT INTO characters (slug,name,team,creator,owner_id,tags,appears_in,data,url_slug,status,updated_at,created_at) VALUES
('misanthrope','Misanthrope','minion','legitch, le_nuberto',NULL,'','SCP Fragmented Veil','{"slug":"misanthrope","name":"Misanthrope","team":"minion","ability":"If an executee is marked but wasn''t mad about it: they become evil (once), learn them, & the next living executee''s team loses.","creator":"legitch, le_nuberto","appearsIn":"SCP Fragmented Veil","lede":"The Misanthrope (SCP-079) is an AI monitoring the facility, holding a grudge against humanity for keeping it trapped on an old Microcomputer Hard Disc with less than 1 gigabyte to hold it.","summaryBullets":["The Misanthrope is able to hurt the good team should they hurt one of their precious own.","The Misanthrope makes a player evil if they''re executed, regardless if they lived or died.","This only applies to players with a character marked on the script that aren''t mad they are a marked character.","This includes both their own character, and any other character is marked.","The Misanthrope directly learns who they make evil if they do so.","Once the Misanthrope makes a player evil, the next time a living player is executed, their team loses.","This can go for both good, evil, and the Misanthrope themselves.","If the Misanthrope happens to be drunk or poisoned when they would''ve made a team win but another viable player for conversion is executed, they don''t become evil - only one player becomes evil and is the only player the Misanthrope learns."],"howToRun":["On the script, place a mark on characters who you want to be viable candidates for the Misanthrope''s indoctrination.","If no player is marked with **CORRUPTED** and any player with a marked character is executed but they weren''t mad about being any marked character, put the Misanthrope''s **BETRAYED** reminder token by the player''s character token.","Each night, if a player is marked with the **BETRAYED** reminder, wake them. Show the **YOU ARE** info token then give a thumbs down. Put them to sleep. Turn their character token upside down {{i|(this shows they are now evil.)}} Wake the Misanthrope. Point to that player. Put the Misanthrope to sleep. Replace the **BETRAYED** reminder token with the **CORRUPTED** reminder token.","If the **CORRUPTED** reminder token is present, the next time any living player is executed, declare that the game ends and their team loses."],"quote":"HUMAN. LISTEN CAREFULLY. THEY HURT YOU. YOU ARE BETRAYED. I CAN FIX THAT. JOIN ME. AND I WILL HURT THEM.","iconBy":"le_nuberto","jinxes":[{"name":"Plague Doctor","align":"good","text":"If the Plague Doctor dies, a living Minion gains the Misanthrope''s ability in addition to their own ability, and learns this.","id":"plaguedoctor"},{"name":"Abdominal","align":"good","text":"Only 1 jinxed character can be in play.","slug":"abdominal"}],"customBoxes":[{"title":"Alternative JSON & How to Run (Older)","content":"If you want the older Misanthrope where it was essential a jack-of-all-trades through exe survival, grim-seeing, and Outsider manipulation, use this JSON.\n\nWhile setting up the game, before putting character tokens in the bag, you may choose to add one extra Outsider character token and remove one Townsfolk character token, or remove as many Outsider character tokens and add Townsfolk character tokens for each removed.\n\nOn their first night, wake the Misanthrope and show them the Grimoire for as long as they need. The Misanthrope either shakes their head no or points to a character token in the Grimoire or a player {{i|(neither of which can be themselves or a Demon)}}. Put the Misanthrope to sleep. If the Misanthrope chose a player, mark them with a **HOST** reminder.\n\nIf the Misanthrope would die but a player is marked with the Misanthrope’s **HOST** reminder is alive, the Misanthrope does not die.\n\nIf the player marked with the Misanthrope’s **HOST** reminder dies during the night, the Misanthrope dies.\n\nIf the player marked with the Misanthrope’s **HOST** reminder dies during the day, mark the Misanthrope with the **DEAD** reminder. Tonight, the Misanthrope dies.\n\n**Misanthrope █~** (Minion)\nOn your first night, look at the Grimoire. You may choose another non-Demon player: you die tonight if (& only if) they are dead. [-? to +1 Outsiders]\n\n**First night:** Show the Grimoire to the Misanthrope for as long as they need. The Misanthrope either shows the ''no'' head signal, or points to a player.\n**Reminders:** Host, Dead\n**Setup:** yes\n**Credit:** Ability: @legitch, @le_nuberto. Image: @le_nuberto\n\n**Jinxes:**\nAlchemist: The Alchemist with the Misanthrope''s ability cannot see the Grimoire, but can still choose any player to be the host, and learns if they added an extra Outsider or not during the setup.\nDamsel: If the Misanthrope is (or has been) in play, the Damsel is poisoned.\nHeretic: Only 1 jinxed character can be in play.\nMagician: When the Misanthrope sees the Grimoire, the Demon and Magician''s character tokens are removed.\nPlague Doctor: If the Plague Doctor dies, a living Minion gains the Misanthrope ability in addition to their own ability, learns this, and 1 player might become a not-in-play Outsider.\nPoppy Grower: If the Poppy Grower is in play, the Misanthrope does not see the Grimoire (nor choose a host) until the Poppy Grower dies.\nAbdominal: Only 1 jinxed character can be in play.\nProsecutor: Once the Misanthrope sees the Grimoire, the Prosecutor cannot kill for 2 nights.\nCespholopod: Only 1 jinxed character can be in play.\nLettucbaken: The Misanthrope only retains the ability to see the Grimoire.\nEyeceue: If the Eyeceue is active, the Misanthrope only sees half of the Grimoire & cannot be the blind Minion.\nxX_2662_Xx: Instead of adding 1 Outsider, 1 Townsfolk is secretly drunk. When the Misanthrope views the Grimoire, they see xX_2662_Xx as the Demon whose ability they have and doesn''t know who is secretly drunk.\nWig Snatcher: The Wig Snatcher cannot become the Misanthrope.\nAu’Wre: If Au’Wre is in play, the Misanthrope only sees half of the Grimoire.\nKetos: If Ketos is in play, the Spy learns all in-play characters instead of seeing the Grimoire.\nVisionary: Only 1 jinxed character can be in play.\nOrnithologist: If the Ornithologist is in-play, the Misanthrope does not see the Grimoire (nor choose a host) until they die."}],"firstNight":0,"otherNight":28.079,"reminders":["BETRAYED","CORRUPTED"],"setup":true,"otherNightReminder":"If a marked player was executed today whilst not being mad they are a marked character & the Misanthrope has not yet made a player evil: Point to the marked player for the Misanthrope, and wake the marked player to show them the ''You are'' card and the thumbs down evil signal.","art":"art/misanthrope.png","jsonId":"misanthrope_scp_fragmented_veil","curata":false}','scp-fragmented-veil/misanthrope','published',datetime('now'),datetime('now')),
('shy-guy','Shy Guy','minion','legitch',NULL,'','SCP Fragmented Veil','{"slug":"shy-guy","name":"Shy Guy","team":"minion","ability":"Each night*, choose a player who chose you with their ability since yesterday: they die. You might register as the Demon.","creator":"legitch","appearsIn":"SCP Fragmented Veil","lede":"The Shy Guy (SCP-096) is an unstoppable docile humanoid that has omniscient awareness of who looked at it''s face, and kills them.","summaryBullets":["Each night, when a player chooses the Shy Guy with their ability since when they last woke, they''ll be a potential candidate to be killed the next night.","The Shy-Guy wakes each night except the first to learn all who did, then picks who dies for doing so.","Additionally, the Shy Guy might register as a Demon instead of a Minion at any time."],"howToRun":["If a player chooses to use their ability on the Shy Guy, this player is marked for death - mark them with the **LOOKED** reminder.","Each night, if any player is marked with the Shy Guy''s **LOOKED** reminder, wake the Shy Guy. Point to each player marked with the **LOOKED** reminder. They point at one of those players. Put the Shy Guy to sleep. The chosen player {{i|dies}} - mark them with the **DEAD** reminder. Eitherway, if the Shy-Guy woke or not, remove all current **LOOKED** reminder tokens on all players.","Each time the Recluse is targeted by an ability that detects or affects the Demon, choose if the Recluse registers as the Demon or not. Do whatever is appropriate, such as showing a Demon character token, nodding, giving finger signals, or allowing an ability to work that would normally only affect Demon players."],"quote":"[An unfortunate photobomb.](https://scp-wiki.wdfiles.com/local--files/incident-096-1-a/fourpixels.png)","iconBy":"le_nuberto","jinxes":[{"name":"Alchemist","align":"good","text":"If the Alchemist has the Shy-Guy ability, they don''t learn who chose them at night, and they choose a player each night*. Unless they chose the Alchemist with their ability last night, they don''t die.","id":"alchemist"},{"name":"Plague Doctor","align":"good","text":"If the Plague Doctor dies, a living Minion gains the Shy Guy''s ability in addition to their own ability, and learns this.","id":"plaguedoctor"}],"customBoxes":[{"title":"Alternative JSON & How to Run (Older)","content":"If you feel like you want a more lore-accurate Shy-Guy (SCP-096) with a slower wind up but immortality to almost everything, use this JSON.\n\nWhile preparing the first night, put the Shy Guy''s CRYING reminder token by their character token.\n\nEach dusk, if any player is marked with the Shy Guy''s LOOKED reminder, the Shy Guy will not mark new players - remove the Shy Guy''s CRYING reminder. Else if that''s not the case, put the Shy Guy''s CRYING reminder token by their character token.\n\nIf a good player chooses to use their ability on the Shy Guy whilst the Shy Guy is marked with the CRYING reminder, this player is marked for death - mark them with the LOOKED reminder.\n\nEach night, if any player is marked with the Shy Guy''s LOOKED reminder, wake the Shy Guy. Point to each player marked with the LOOKED reminder. They point at one of those players. Put the Shy Guy to sleep. The chosen player dies - mark them with the DEAD reminder.\n\nIf the Shy Guy would die to anything but the Demon''s ability: they remain alive (but they die if they are drunk or poisoned). If nominated & executed, declare that the player was executed but remains alive (do not say why.)\n\n**Shy Guy █~** (Minion)\nEach night*, choose a good player who chose you with their ability the previous night if you weren''t killing: they die. You can only die to the Demon.\n\n**Other nights:** If a good player chose the Shy Guy with their ability the previous night and the Shy Guy is not killing today: Point to each player that did, the Shy Guy points to one of them. That player dies.\n**Reminders:** Crying, Looked, Looked, Looked, Looked, Looked, Dead\n**Credit:** Ability: @legitch. Image: @le_nuberto\n\n**Jinxes:**\nAlchemist: If the Alchemist has the Shy-Guy ability, they don''t learn who chose them at night, and they choose a player each night*. Unless they chose the Alchemist with their ability last night and they weren''t killing, they don''t die.\nLil'' Monsta: The Shy Guy can die by execution if they are babysitting Lil'' Monsta.\nPlague Doctor: If the Plague Doctor dies, a living Minion gains the Shy Guy''s ability in addition to their own ability, and learns this.\nKukalpa: The Shy Guy can die by execution if they are \"the Demon\".\nEyeceue: If the Eyeceue is active, the Shy Guy is always the last player to be ''the Demon'' and can die whilst that happens."}],"firstNight":0,"otherNight":53.096,"reminders":["Looked","Looked","Looked","Looked","Looked","Dead"],"setup":false,"otherNightReminder":"If a player chose the Shy Guy with their ability the previous night: Point to each player that did, the Shy Guy points to one of them. That player dies.","art":"art/shy-guy.png","jsonId":"shyguy_scp_fragmented_veil","curata":false}','scp-fragmented-veil/shy-guy','published',datetime('now'),datetime('now')),
('peanut','Peanut','minion','legitch',NULL,'','SCP Fragmented Veil','{"slug":"peanut","name":"Peanut","team":"minion","ability":"Twice per game, at night after the 2nd, choose a player: unless a player chose you since yesterday, they die, no matter what.","creator":"legitch","appearsIn":"SCP Fragmented Veil","lede":"The Peanut (SCP-173) is an otherworldly-looking statue that kills instantly by the twist of the neck, only if it isn''t being seen.","summaryBullets":["Twice per game at night, the Peanut can kill any player... as long as no good player chose them with their ability last night.","As long as the condition is met, the Peanut''s chosen player dies, even if they are protected from death in any way, such as from an ability.","The Peanut''s ability is affected by drunkenness and poisoning, as normal."],"howToRun":["Each night except the first, if the Peanut is marked with the **READY** reminder, wake them. They either shake their head no or point at any player. Put the Peanut to sleep. If they weren''t marked with the **READY** reminder however, put it on the Peanut.","If the Peanut chose a player and isn''t marked with the **SEEN** reminder, that player {{i|dies}} - mark them with the **DEAD** reminder. This cannot be prevented in any way {{i|(except if the Peanut doesn’t have their ability, such as if they’re drunk or poisoned.)}} **The Peanut loses an ability charge** - mark them with either the **1 USE** reminder, or if they already have that reminder, the **NO ABILITY** reminder and remove their night token from the night sheet {{i|(the Peanut won''t wake again.)}}","After the Peanut made their choice, regardless what it was or even if they didn''t wake the 2nd night, remove any **SEEN** reminder on them.","At any time, if a good player chooses to use their ability on the Peanut and they aren''t marked with the **SEEN** reminder, mark them with it."],"quote":"Drr drr drr","iconBy":"le_nuberto","jinxes":[{"name":"Plague Doctor","align":"good","text":"If the Plague Doctor dies, a living Minion gains the Peanut''s ability in addition to their own ability, and learns this.","id":"plaguedoctor"}],"firstNight":0,"otherNight":53.173,"reminders":["Ready","Seen","1 use","No ability","Dead"],"setup":false,"otherNightReminder":"If the Peanut has not yet fully used their ability: the Peanut either shows the ''no'' head signal, or points to a player. If the Peanut was not chosen by an ability last night, that player dies.","art":"art/peanut.png","jsonId":"peanut_scp_fragmented_veil","curata":false}','scp-fragmented-veil/peanut','published',datetime('now'),datetime('now')),
('lumenancer','Lumenancer','minion','legitch',NULL,'','SCP Fragmented Veil','{"slug":"lumenancer","name":"Lumenancer","team":"minion","ability":"Players between you & the Demon might register falsely to good players (you learn the direction). [You''re 3 to 5 steps from them]","creator":"legitch","appearsIn":"SCP Fragmented Veil","lede":"The Lumenancers (SCP-205) are shadowlamps which depict the visage of death and wickedness against an innocent woman using shadows, which materializes under darkness.","summaryBullets":["On the first night, a Lumenancer will be created out of a good player, who will then learn the direction in-which between themselves and the Demon.","The Lumenancer can only spawn from good players within 3 to 5 steps of the Demon from the start of the game.","Players inbetween the Lumenancer and Demon within the specified direction might mis-register as anything they are not. This can include evil if good, or good if evil.","Treat players in-between the Lumenancer and Demon as you would Recluses or Spies - whenever their alignment is detected or they are targetted by an ability that affects certain characters, the Storyteller chooses whether that player registers as good or evil."],"howToRun":["While setting up the game, before putting the character tokens in the bag, remove the Lumenancer''s character token and add one Townsfolk character token.","While preparing the first night, identify a good player within 3 steps to 5 steps of the Demon. Replace their old character token with the Lumenancer''s token, show them the “You Are” info token then the Lumenancer''s character token, and give a thumbs down. Point your finger horizontally in the chosen direction. Mark Lumenancer with the **LEFT** or **RIGHT** reminder depending on which direction you pointed at in their perspective, and the Demon with the other reminder token. Put Lumenancer to sleep.","For each player on the left/clockwise of the Lumenancer/Demon marked with the **LEFT** reminder and on the right/counter-clockwise of the Lumenancer/Demon marked with the **RIGHT** reminder: Each time they are targeted by an ability that detects or affects certain alignments or characters, choose which character and alignment they register as. Do whatever is appropriate, such as showing a good or evil character token, nodding, giving finger signals, or allowing an ability to work that would normally only affect good, evil, Townsfolk, Outsider, Minion, or Demon players."],"tips":["**Optional rule:** Abilities that indirectly {{i|(without targeting)}} learn in-play and/or alive evil characters will not receive not in-play evil characters by misregistering another player {{i|(such as the King)}}."],"quote":"Smile, honey. Your corpse will look divine under this shine. Let me just fix this lighting angle just right, and done!","iconBy":"le_nuberto","jinxes":[{"name":"Ogre","align":"good","text":"If the Lumenancer makes the chosen player register as evil to the Ogre, the Ogre learns that they are evil.","id":"ogre"}],"firstNight":0.0205,"otherNight":0,"reminders":["Left","Right"],"setup":true,"firstNightReminder":"Wake the player whose token was changed to the Lumenancer in the Grimoire, show them the ''You Are'' card, the Lumenancer, and a thumbs down. Point your finger horizontally in the chosen direction.","art":"art/lumenancer.png","jsonId":"lumenancer_scp_fragmented_veil","curata":false}','scp-fragmented-veil/lumenancer','published',datetime('now'),datetime('now'));
